def set_hyperparams(self, new_params):
        """Set the (free) hyperparameters.

        Parameters
        ----------
        new_params : :py:class:`Array` or other Array-like
            New values of the free parameters.

        Raises
        ------
        ValueError
            If the length of `new_params` is not consistent with :py:attr:`self.params`.
        """
        import numpy as np

        new_arr = np.asarray(new_params)
        try:
            expected_len = len(self.params)
        except TypeError:
            raise ValueError("`self.params` must be a sequence with a defined length.") from None

        if new_arr.size != expected_len:
            raise ValueError(
                f"Length of new_params ({new_arr.size}) does not match expected length ({expected_len})."
            )

        # Preserve original type/structure if possible
        if isinstance(self.params, np.ndarray):
            self.params = new_arr.reshape(self.params.shape)
        else:
            # Assume list-like; replace contents
            if hasattr(self.params, "__setitem__"):
                for i, val in enumerate(new_arr):
                    self.params[i] = val
            else:
                self.params = new_arr.tolist()

