mgc_code:
def get(cls, reactor, source='graphite', **options):
        """Get Alert Class by source."""
        # Gather all subclasses recursively
        def _all_subclasses(c):
            subs = set(c.__subclasses__())
            for sub in list(subs):
                subs.update(_all_subclasses(sub))
            return subs

        for subclass in _all_subclasses(cls):
            if getattr(subclass, "source", None) == source:
                return subclass(reactor, **options)

        raise ValueError(f"No Alert class found for source '{source}'")

