mgc_code:
def _is_postgres(self):
        """ Determine if the running engine is postgres """
        try:
            # Prefer a direct engine attribute
            engine = getattr(self, "engine", None)
            # Fallback to a session's bound engine
            if engine is None and hasattr(self, "session"):
                engine = getattr(self.session, "bind", None)
            if engine is None:
                return False

            # SQLAlchemy Engine or Connection objects have a .dialect attribute
            dialect = getattr(engine, "dialect", None)
            if dialect is None:
                # If a URL string was provided directly
                name = str(engine).lower()
            else:
                name = getattr(dialect, "name", "").lower()

            return name.startswith("postgresql")
        except Exception:
            return False

