mgc_code:
def _serialize_xml(self, root):
        """Serialize XML data into string

        It serializes the dynamic xml created and converts
        it to a string. This is done before sending the
        xml to the ILO.

        :param root: root of the dynamic xml.
        """
        if root is None:
            return ''
        try:
            from xml.etree.ElementTree import tostring, Element, ElementTree
            # If an ElementTree instance, get its root element
            if isinstance(root, ElementTree):
                root = root.getroot()
            # Ensure we have an Element to serialize
            if isinstance(root, Element):
                return tostring(root, encoding='unicode')
            # Fallback: try to convert to string directly
            return str(root)
        except Exception as exc:
            raise ValueError(f"Failed to serialize XML: {exc}")

