def get_resources(cls):
        """Returns Ext Resources."""
        resources = {"js": [], "css": []}
        for base in reversed(cls.__mro__):
            for attr in ("js", "css"):
                val = getattr(base, attr, None)
                if not val:
                    continue
                if isinstance(val, (list, tuple)):
                    resources[attr].extend(val)
                else:
                    resources[attr].append(val)
        for key in resources:
            seen = set()
            uniq = []
            for item in resources[key]:
                if item not in seen:
                    seen.add(item)
                    uniq.append(item)
            resources[key] = uniq
        return resources

