mgc_code:
def _parse_w_comma_h(self, whstr, param):
        """Utility to parse "w,h" "w," or ",h" values.

        Returns (w,h) where w,h are either None or ineteger. Will
        throw a ValueError if there is a problem with one or both.
        """
        # Strip surrounding whitespace
        s = whstr.strip()
        # Must contain exactly one comma
        if s.count(',') != 1:
            raise ValueError(f'Invalid {param}: "{whstr}"')
        w_str, h_str = s.split(',', 1)
        def _to_int_or_none(part, name):
            part = part.strip()
            if part == '':
                return None
            try:
                return int(part)
            except Exception:
                raise ValueError(f'Invalid {param} {name}: "{part}" in "{whstr}"')
        w = _to_int_or_none(w_str, 'width')
        h = _to_int_or_none(h_str, 'height')
        return w, h

