def predict(self, **kwargs):
        """
        Do the workflow prediction (done after training, with new data)
        """
        # Ensure a trained model is available
        if not hasattr(self, "model"):
            raise AttributeError("The instance has no attribute 'model'; training may not have been performed.")
        # Resolve input data
        if "X" in kwargs:
            X = kwargs["X"]
        elif "data" in kwargs:
            X = kwargs["data"]
        elif "input" in kwargs:
            X = kwargs["input"]
        else:
            raise ValueError("Missing input data for prediction; provide 'X', 'data', or 'input' keyword argument.")
        # Perform prediction using the appropriate method
        if hasattr(self.model, "predict"):
            return self.model.predict(X)
        elif hasattr(self.model, "transform"):
            return self.model.transform(X)
        else:
            raise AttributeError("The model does not implement 'predict' or 'transform' methods.")

