mgc_code:
def get_ip4():
    """
    return all ip v4 address of current computer
    :return:
    """
    import socket

    addrs = set()
    hostname = socket.gethostname()

    try:
        for info in socket.getaddrinfo(hostname, None, socket.AF_INET):
            addrs.add(info[4][0])
    except socket.gaierror:
        pass

    try:
        _, _, iplist = socket.gethostbyname_ex(hostname)
        addrs.update(iplist)
    except socket.error:
        pass

    if not addrs:
        addrs.add('127.0.0.1')

    return sorted(addrs)

