def add_update_topology_db(self, **params):
        """Add or update an entry to the topology DB. """
        # Initialize in‑memory storage if not present
        if not hasattr(self, "_topology_db"):
            self._topology_db = {}

        # Require a unique identifier for the entry; default to 'id'
        if "id" not in params:
            raise ValueError("Parameter 'id' is required to add or update a topology entry.")
        entry_id = params["id"]

        # If the entry exists, update its fields; otherwise, create a new one
        if entry_id in self._topology_db:
            self._topology_db[entry_id].update(params)
        else:
            # Store a shallow copy to avoid external mutation
            self._topology_db[entry_id] = dict(params)

        # Return the stored entry for convenience
