def task_property_present_predicate(service, task, prop):
    """ True if the json_element passed is present for the task specified.
    """
    # Resolve task data
    if isinstance(task, dict):
        data = task
    else:
        # Try common service access patterns
        for accessor in (
            lambda s, t: s.get_task(t),
            lambda s, t: s[t],
            lambda s, t: s.get(t),
        ):
            try:
                data = accessor(service, task)
                break
            except Exception:
                data = None
        else:
            return False

    # Determine presence of the property
    if isinstance(data, dict):
        return prop in data and data[prop] is not None
    if isinstance(data, (list, tuple)):
        return any(isinstance(item, dict) and prop in item and item[prop] is not None for item in data)
    return False

