def _init_app(self, app):
        """Initialize actions with the given :class:`flask.Flask` object.

        :param app: The flask application object
        :type app: :class:`~flask.Flask`
        """
        # Store a reference to the Flask app
        self.app = app

        # Register the extension in Flask's extensions registry
        if not hasattr(app, "extensions"):
            app.extensions = {}
        app.extensions[self.__class__.__name__] = self

        # Apply any default configuration values defined on the instance
        for key, value in getattr(self, "default_config", {}).items():
            app.config.setdefault(key, value)

        # Initialise any sub‑actions that also support Flask integration
        for action in getattr(self, "actions", []):
            init = getattr(action, "init_app", None)
            if callable(init):
                init(app)

