def get_migrations_dir(graph):
    """
    Resolve the migrations directory path.

    Either take the directory from a component of the object graph or by
    using the metaata's path resolution facilities.

    """
    from pathlib import Path

    # Try attribute access
    dir_candidate = getattr(graph, "migrations_dir", None)
    if dir_candidate is None:
        # Try dict‑style access
        try:
            dir_candidate = graph["migrations_dir"]
        except (TypeError, KeyError):
            dir_candidate = None

    if dir_candidate is not None:
        return Path(dir_candidate).expanduser().resolve()

    # Fallback to a meta‑object that can resolve paths
    meta = getattr(graph, "meta", None)
    if meta is not None:
        resolve = getattr(meta, "resolve_path", None)
        if callable(resolve):
            try:
                resolved = resolve("migrations")
                if resolved:
                    return Path(resolved).expanduser().resolve()
            except Exception:
                pass

