        salt '*' quota.off
    """
    cmd = "quotaoff -a"
    result = __salt__["cmd.run_all"](cmd)
    if result.get("retcode") == 0:
        return {"result": True, "changes": {}, "comment": "Quota system turned off"}
    return {
        "result": False,
        "changes": {},
        "comment": result.get("stderr", "Failed to turn off quota system"),
    }

