def validate(self, value):
        """Validate string by regex
        :param value: str
        :return:
        """
        import re
        pattern = getattr(self, "regex", None)
        if pattern is None:
            raise ValueError("No regex pattern defined on the instance.")
        if isinstance(pattern, str):
            pattern = re.compile(pattern)
        if not isinstance(value, str):
            raise TypeError(f"Expected a string for validation, got {type(value).__name__}")
        return bool(pattern.fullmatch(value))

