def download_file(client, bucket, remote_path, local_path, overwrite=False):
    """Downloads a file from a bucket.

    TODO: docstring"""
    import os

    if not overwrite and os.path.exists(local_path):
        raise FileExistsError(f"File '{local_path}' already exists and overwrite is False.")

    os.makedirs(os.path.dirname(os.path.abspath(local_path)) or '.', exist_ok=True)

    # Try common client interfaces
    if hasattr(client, "download_blob_to_file"):
        # Google Cloud Storage style: client.download_blob_to_file(bucket, remote_path, file_obj)
        with open(local_path, "wb") as f:
            client.download_blob_to_file(bucket, remote_path, f)
    elif hasattr(client, "download_file"):
        # Boto3 style: client.download_file(bucket, remote_path, local_path)
        client.download_file(bucket, remote_path, local_path)
    elif hasattr(client, "get_object"):
        # Generic S3 get_object style
        response = client.get_object(Bucket=bucket, Key=remote_path)
        with open(local_path, "wb") as f:
            for chunk in response.get("Body", b""):
                f.write(chunk)
    else:
        raise AttributeError("Client does not support a known download method.")

solution:
left, right = np.asarray(left), np.asarray(right)

# shape compat
if left.shape != right.shape:
    return False

# Object arrays can contain None, NaN and NaT.
# string dtypes must be come to this path for NumPy 1.7.1 compat
if is_string_dtype(left) or is_string_dtype(right):

    if not strict_nan:
        # isna considers NaN and None to be equivalent.
        return lib.array_equivalent_object(
            ensure_object(left.ravel()), ensure_object(right.ravel()))

    for left_value, right_value in zip(left, right):
        if left_value is NaT and right_value is not NaT:
            return False

        elif isinstance(left_value, float) and np.isnan(left_value):
            if (not isinstance(right_value, float) or
                    not np.isnan(right_value)):
                return False
        else:
            if left_value != right_value:
                return False
    return True

# NaNs can occur in float and complex arrays.
if is_float_dtype(left) or is_complex_dtype(left):

    # empty
    if not (np.prod(left.shape) and np.prod(right.shape)):
        return True
    return ((left == right) | (isna(left) & isna(right))).all()

# numpy will will not allow this type of datetimelike vs integer comparison
elif is_datetimelike_v_numeric(left, right):
    return False

# M8/m8
elif needs_i8_conversion(left) and needs_i8_conversion(right):
    if not is_dtype_equal(left.dtype, right.dtype):
        return False

    left = left.view('i8')
    right = right.view('i8')

# if we have structured dtypes, compare first
if (left.dtype.type is np.void or
        right.dtype.type is np.void):
    if left.dtype != right.dtype:
        return False

return np.array_equal(left, right)

