mgc_code:
def word_matches(s1, s2, n=3):
    """
        Word-level n-grams that match between two strings

        Args:
            s1: a string
            s2: another string
            n: an int for the n in n-gram

        Returns:
            set: the n-grams found in both strings
    """
    words1 = s1.split()
    words2 = s2.split()
    if n <= 0:
        return set()
    def ngrams(words):
        return {tuple(words[i:i + n]) for i in range(len(words) - n + 1)} if len(words) >= n else set()
    common = ngrams(words1) & ngrams(words2)
    return {' '.join(gram) for gram in common}

