mgc_code:
def present(name, auth=None, **kwargs):
    """
    Ensure domain exists and is up-to-date

    name
        Name of the domain

    enabled
        Boolean to control if domain is enabled

    description
        An arbitrary description of the domain
    """
    if not hasattr(present, "_store"):
        present._store = {}
    store = present._store

    domain = store.get(name, {
        "name": name,
        "enabled": kwargs.get("enabled", True),
        "description": kwargs.get("description", ""),
        "metadata": {}
    })

    # Update known fields
    for field in ("enabled", "description"):
        if field in kwargs:
            domain[field] = kwargs[field]

    # Store any additional keyword arguments as metadata
    extra = {k: v for k, v in kwargs.items() if k not in ("enabled", "description")}
    if extra:
        domain.setdefault("metadata", {}).update(extra)

    store[name] = domain
    return domain

