mgc_code:
def gray2bin(G):
    """Convert a gray-coded vector into a binary-coded vector."""
    g = list(G)
    if not g:
        return []
    b = [g[0]]
    for bit in g[1:]:
        b.append(b[-1] ^ bit)
    return b

