mgc_code:
def _havdalah_datetime(self):
        """Compute the havdalah time based on settings."""
        from datetime import timedelta

        base = getattr(self, "_sunset", None)
        if base is None:
            raise ValueError("Sunset time not set for havdalah calculation")
        offset = getattr(self.settings, "havdalah_offset", 0)
        try:
            minutes = int(offset)
        except Exception:
            minutes = 0
        return base + timedelta(minutes=minutes)

