def is_protein_or_chemical(agent):
    """Return True if the agent is a protein/protein family or chemical."""
    if isinstance(agent, dict):
        typ = agent.get('type', '')
        if isinstance(typ, str):
            typ = typ.lower()
            return any(k in typ for k in ('protein', 'family', 'chemical', 'compound', 'drug'))
        return False
    if isinstance(agent, str):
        low = agent.lower()
        keywords = ('protein', 'family', 'enzyme', 'acid', 'inhibitor', 'compound', 'chemical', 'drug')
        if any(k in low for k in keywords):
            return True
        # common protein/gene symbol patterns (e.g., all caps with optional numbers/hyphens)
        if low.isupper() and any(c.isdigit() for c in low):
            return True
        if any(c.isdigit() for c in low) and '-' in low:
            return True
    return False

