def _environment_sanity_check(environment):
    """Perform a sanity check on the environment."""
    from collections.abc import Mapping

    if environment is None:
        return True

    if not isinstance(environment, Mapping):
        raise TypeError("environment must be a mapping of strings to strings")

    for key, value in environment.items():
        if not isinstance(key, str):
            raise TypeError(f"environment key {key!r} is not a string")
        if not isinstance(value, str):
            raise TypeError(f"environment value for key {key!r} is not a string")
        if key == "":
            raise ValueError("environment contains an empty string key")
        if "\x00" in key or "\x00" in value:
            raise ValueError(f"environment key/value for {key!r} contains null byte")
    return True

