def _cleanup_keys_with_confirmation(self, keys_to_delete):
    """Asks confirmation and then deletes entries with keys.

    Args:
      keys_to_delete: list of datastore keys for which entries should be deleted
    """
    if not keys_to_delete:
        return
    prompt = f"Delete {len(keys_to_delete)} entr{'y' if len(keys_to_delete) == 1 else 'ies'}? (y/N): "
    try:
        response = input(prompt).strip().lower()
    except EOFError:
        response = ''
    if response not in ('y', 'yes'):
        print("Deletion aborted.")
        return
    for key in keys_to_delete:
        try:
            # Assume the datastore interface provides a delete method.
            self._datastore.delete(key)
        except Exception as exc:  # pragma: no cover
            print(f"Failed to delete key {key!r}: {exc}")

