mgc_code:
def exponential_backoff(fn, sleeptime_s_max=30 * 60):
    """Calls `fn` until it returns True, with an exponentially increasing wait time between calls"""
    import time
    _sleep = 0.1
    while True:
        result = fn()
        if result:
            return result
        time.sleep(_sleep)
        _sleep = min(_sleep * 2, sleeptime_s_max)

