def _parse_acl_config(self, acl_config):
        """Parse configured ACLs and rules

        ACLs are returned as a dict of rule sets:
        {<eos_acl1_name>: set([<eos_acl1_rules>]),
         <eos_acl2_name>: set([<eos_acl2_rules>]),
         ...,
        }
