def get_assigned_work_unit(self, worker_id, work_spec_name,
                               work_unit_key):
        """get a specific WorkUnit that has already been assigned to a
        particular worker_id
        """
        # Attempt direct dictionary lookup if the container supports it
        key = (worker_id, work_spec_name, work_unit_key)
        assigned = getattr(self, "assigned_work_units", None)

        if isinstance(assigned, dict):
            try:
                return assigned[key]
            except KeyError:
                pass

        # Fallback to iterable search (list, set, etc.)
        if assigned is not None:
            for unit in assigned:
