def _api_all_limits(self):
        """Glances API RESTful implementation.

        Return the JSON representation of all the plugins limits
        HTTP/200 if OK
        HTTP/400 if plugin is not found
        HTTP/404 if others error
        """
        try:
            limits = {}
            for plugin in getattr(self, "plugins", []):
                # Each plugin should have a name attribute and a limits method or property
                name = getattr(plugin, "name", None)
                if not name:
                    continue
                # Try to get limits; could be a method or attribute
                plugin_limits = None
                if hasattr(plugin, "limits"):
                    attr = getattr(plugin, "limits")
                    plugin_limits = attr() if callable(attr) else attr
                elif hasattr(plugin, "get_limits"):
                    plugin_limits = plugin.get_limits()
                if plugin_limits:
                    limits[name] = plugin_limits
            return json.dumps(limits), 200
        except Exception as e:
            # If a specific plugin is not found or other error occurs
            error_msg = {"error": str(e)}
            return json.dumps(error_msg), 400 if "not found" in str(e).lower() else 404

