def remove_temp_copy(self):
        """
        Removes a temporary copy of the MAGICC version shipped with Pymagicc.
        """
        import os
        import shutil

        temp_path = getattr(self, "_temp_copy_path", None)
        if not temp_path:
            return

        # Remove the temporary directory if it exists
        if os.path.isdir(temp_path):
            try:
                shutil.rmtree(temp_path)
            except Exception:
                # If removal fails, ignore to avoid breaking the caller
                pass

        # Clean up the attribute reference
        try:
            del self._temp_copy_path
        except AttributeError:
            pass

