    """Creates a mapper object on witch add_mapping() and remove_mapping()
    can be called. It uses fire-and-forget notifications so it has a very
    low overhead and latency but a little less guarantees."""
    import threading

    class _Mapper:
        __slots__ = ('_agent', '_map')

        def __init__(self, agent):
            self._agent = agent
            self._map = {}

        def _fire(self, func, *args, **kwargs):
            t = threading.Thread(target=func, args=args, kwargs=kwargs, daemon=True)
            t.start()

        def add_mapping(self, key, value):
            """Add a mapping from *key* to *value* and notify the agent."""
            self._map[key] = value
            if hasattr(self._agent, 'notify'):
                self._fire(self._agent.notify, 'add', key, value)

        def remove_mapping(self, key):
            """Remove the mapping for *key* (if present) and notify the agent."""
            if key in self._map:
                value = self._map.pop(key)
                if hasattr(self._agent, 'notify'):
                    self._fire(self._agent.notify, 'remove', key, value)

    return _Mapper(agent)

