mgc_code:
def cli(obj, role, scopes, delete):
    """Add or delete role-to-permission lookup entry."""
    if delete:
        if role in obj:
            current = obj[role]
            for scope in scopes:
                current.discard(scope)
            if not current:
                del obj[role]
    else:
        current = obj.setdefault(role, set())
        for scope in scopes:
            current.add(scope)
    return obj

