def gene_ids(self):
        """
        Return IDs of all genes which overlap this variant. Calling
        this method is significantly cheaper than calling `Variant.genes()`,
        which has to issue many more queries to construct each Gene object.
        """
        # Prefer a direct many‑to‑many relationship if it exists.
        # ``self.genes`` is assumed to be a manager that can return IDs without
        # instantiating full ``Gene`` objects.
        try:
            return list(self.genes.values_list('id', flat=True))
        except Exception:
            # Fall back to an explicit through‑model (e.g. VariantGene) that
            # stores the foreign‑key to ``Gene`` as ``gene_id``.
            if hasattr(self, 'variantgene_set'):
                return list(self.variantgene_set.values_list('gene_id', flat=True))
            # If neither accessor is available, re‑raise the original error.
            raise

