def remove(text, what, count=None, strip=False):
    """
    Like ``replace``, where ``new`` replacement is an empty string.
    """
    if what == '':
        result = text
    else:
        if count is None:
            result = text.replace(what, '')
        else:
            result = text.replace(what, '', count)
    if strip:
        result = result.strip()
    return result

