def check_thresholds(self):
        """
        Checks current usage against configured thresholds for all limits
        for this service.

        :returns: a dict of limit name to :py:class:`~.AwsLimit` instance
          for all limits that crossed one or more of their thresholds.
        :rtype: :py:obj:`dict` of :py:class:`~.AwsLimit`
        """
        if not self._have_usage:
            self.find_usage()
        ret = {}
        for name, limit in self.limits.items():
            if limit.check_thresholds() is False:
                ret[name] = limit
        return ret

mgc_code:
def check_thresholds(self):
        """
        Checks current usage against configured thresholds for all limits
        for this service.

        :returns: a dict of limit name to :py:class:`~.AwsLimit` instance
          for all limits that crossed one or more of their thresholds.
        :rtype: :py:obj:`dict` of :py:class:`~.AwsLimit`
        """
        crossed = {}
        limits = getattr(self, "limits", {})
        for name, limit in limits.items():
            usage = getattr(limit, "usage", None)
            thresholds = getattr(limit, "thresholds", [])
            if usage is None or not thresholds:
                continue
            try:
                iter(thresholds)
            except TypeError:
                thresholds = [thresholds]
            for th in thresholds:
                try:
                    if usage >= th:
                        crossed[name] = limit
                        break
                except Exception:
                    continue
        return crossed

