def main():
    """
    This generates the research document based on the results of 
    the various programs and includes RST imports for introduction
    and summary
    """
    import pathlib

    base_path = pathlib.Path(__file__).parent
    intro_path = base_path / "intro.rst"
    summary_path = base_path / "summary.rst"
    results_dir = base_path / "results"

    parts = []

    # Introduction import
    if intro_path.is_file():
        parts.append(f".. include:: {intro_path.name}\n")
    else:
        parts.append(".. include:: intro.rst\n")

    # Append results from each program
    if results_dir.is_dir():
        for result_file in sorted(results_dir.iterdir()):
            if result_file.is_file() and result_file.suffix in {".txt", ".rst", ".md"}:
                parts.append("\n")
                parts.append(f".. include:: {result_file.relative_to(base_path)}\n")
    else:
        parts.append("\n.. note:: No results directory found.\n")

    # Summary import
    if summary_path.is_file():
        parts.append(f"\n.. include:: {summary_path.name}\n")
    else:
        parts.append("\n.. include:: summary.rst\n")

    return "".join(parts)

