mgc_code:
def samefile(file1, file2):
    # type: (str, str) -> bool
    """Provide an alternative for os.path.samefile on Windows/Python2"""
    import os
    try:
        s1 = os.stat(file1)
        s2 = os.stat(file2)
        if getattr(s1, "st_ino", None) is not None and getattr(s2, "st_ino", None) is not None:
            if s1.st_ino == s2.st_ino and s1.st_dev == s2.st_dev:
                return True
    except OSError:
        return False
    p1 = os.path.normcase(os.path.abspath(file1))
    p2 = os.path.normcase(os.path.abspath(file2))
    return p1 == p2

