def destroy(self):
        """
        destroy a client.
        """
        # Attempt to gracefully close common resource attributes
        for _attr in ("session", "socket", "connection", "client", "pool"):
            _res = getattr(self, _attr, None)
            if _res is None:
                continue
            _close = getattr(_res, "close", None)
            if callable(_close):
                try:
                    _close()
                except Exception:
                    pass
        # Mark the instance as destroyed to prevent further use
        setattr(self, "_destroyed", True)

